with open('optimized.pkl','rb') as f:m,x=pickle.load(f)
fig=plt.figure(figsize=(12,6))
for k,view in enumerate([(10,-80),(20,-25)]):
 ax=fig.add_subplot(1,2,k+1,projection='3d')
 for b in m.GetBonds():
