  ax.plot(*p.T,color=color,lw=1.5)
 colors={'C':'#555555','H':'#cccccc','O':'red','N':'blue'}
 for i,a in enumerate(m.GetAtoms()):
  el=a.GetSymbol();ax.scatter(*x[i],c=colors[el],s=60 if el!='H' else 18,depthshade=False)
